// Generates runtime/src/validation/generated-types.ts from the checked-in
// canonical schema at references/contracts-v2.schema.json (JSON Schema Draft
// 2020-12, $id urn:blackceo:motion:contracts:2.0).
//
// Per Directive Section 5.1, JSON Schema is canonical and TypeScript types are
// generated from the checked-in schemas. Never hand-edit the generated file;
// change the schema and re-run: npm run generate-types
//
// Method: each $defs entry is compiled with json-schema-to-typescript using
// the def itself as the root schema (with the full $defs attached so internal
// "#/$defs/..." references resolve). Exported declarations are collected and
// deduplicated by type name. A name that reappears with different text aborts
// generation, because that would mean the schema produces diverging types.

import { compile } from "json-schema-to-typescript";
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const scriptDir = dirname(fileURLToPath(import.meta.url));
const runtimeRoot = resolve(scriptDir, "..");
const schemaPath = resolve(runtimeRoot, "..", "references", "contracts-v2.schema.json");
const outPath = resolve(runtimeRoot, "src", "validation", "generated-types.ts");

const schema = JSON.parse(readFileSync(schemaPath, "utf8"));
const defs = schema.$defs;
if (!defs || typeof defs !== "object") {
  throw new Error(`No $defs found in ${schemaPath}`);
}

function splitDeclarations(ts) {
  // json-schema-to-typescript emits top-level declarations starting at column
  // 0 with "export ". Everything before the first export is banner material.
  const blocks = [];
  let current = null;
  for (const line of ts.split("\n")) {
    if (line.startsWith("export ")) {
      if (current) blocks.push(current);
      current = line;
    } else if (current !== null) {
      current += "\n" + line;
    }
  }
  if (current) blocks.push(current);
  return blocks
    .map((b) => b.replace(/\s+$/u, ""))
    .filter((b) => b.trim().length > 0);
}

function declarationName(block) {
  const m = block.match(/^export (?:interface|type|enum) ([A-Za-z0-9_]+)/u);
  if (!m) throw new Error(`Cannot find type name in declaration: ${block.slice(0, 80)}`);
  return m[1];
}

const byName = new Map();
const order = [];
for (const defName of Object.keys(defs)) {
  const root = JSON.parse(JSON.stringify(defs[defName]));
  root.$defs = defs;
  const ts = await compile(root, defName, { bannerComment: "" });
  for (const block of splitDeclarations(ts)) {
    const name = declarationName(block);
    if (byName.has(name)) {
      if (byName.get(name) !== block) {
        throw new Error(
          `Generated type "${name}" differs between compilations. ` +
            "The schema yields diverging types; fix the schema instead of the generated file."
        );
      }
      continue;
    }
    byName.set(name, block);
    order.push(name);
  }
}

const header = [
  "// GENERATED FILE. DO NOT EDIT BY HAND.",
  "// Generated by runtime/scripts/generate-types.mjs from the checked-in",
  "// canonical schema references/contracts-v2.schema.json",
  "// (JSON Schema Draft 2020-12, $id urn:blackceo:motion:contracts:2.0).",
  "// Per Directive Section 5.1 the JSON Schema is canonical; regenerate with:",
  "//   npm run generate-types",
  "",
].join("\n");

const body = order.map((name) => byName.get(name)).join("\n\n");
mkdirSync(dirname(outPath), { recursive: true });
writeFileSync(outPath, header + body + "\n", "utf8");
console.log(`Wrote ${outPath} with ${order.length} types: ${order.join(", ")}`);
